  "inlineSchema": "// =============================================================\n//  Flaire – database schema\n//  Provider: SQLite (single file, no external service needed)\n//  ORM:      Prisma\n// =============================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ---------- Account / profile ----------\n\nmodel User {\n  id           String    @id @default(cuid())\n  email        String    @unique\n  username     String    @unique\n  passwordHash String\n  firstName    String?\n  lastName     String?\n  dateOfBirth  DateTime?\n  timezone     String    @default(\"UTC\")\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  // Profile / medical context\n  conditions String? // JSON array of diagnosis strings\n  allergies  String? // JSON array\n  avatarUrl  String?\n\n  // Relations\n  symptoms       Symptom[]\n  medications    Medication[]\n  doseLogs       MedicationDose[]\n  checkIns       DailyCheckIn[]\n  dietLogs       DietLog[]\n  flares         FlareEvent[]\n  medicalRecords MedicalRecord[]\n  posts          CommunityPost[]\n  comments       CommunityComment[]\n  insights       Insight[]\n  calendarEvents CalendarEvent[]\n  sessions       Session[]\n}\n\nmodel Session {\n  id        String   @id @default(cuid())\n  userId    String\n  token     String   @unique\n  createdAt DateTime @default(now())\n  expiresAt DateTime\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n}\n\n// ---------- Symptom tracking (body map + general) ----------\n\nmodel Symptom {\n  id           String   @id @default(cuid())\n  userId       String\n  // bodyPart is null for general / non-localized entries (e.g. fatigue)\n  bodyPart     String?\n  bodyPartName String?\n  // Either a single symptom name (for general) or multiple tags (for body-map)\n  symptoms     String // JSON array of strings: e.g. [\"Pain\",\"Swelling\"]\n  severity     Int // 1..10\n  notes        String?\n  view         String? // 'front' | 'side' | null\n  loggedAt     DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, loggedAt])\n  @@index([userId, bodyPart])\n}\n\n// ---------- Medications ----------\n\nmodel Medication {\n  id            String    @id @default(cuid())\n  userId        String\n  name          String\n  dosage        String // e.g. \"200mg\"\n  frequency     String // e.g. \"Twice daily\"\n  timesPerDay   Int       @default(1)\n  scheduleTimes String // JSON array of HH:mm strings\n  startDate     DateTime\n  endDate       DateTime?\n  color         String    @default(\"#7293BB\")\n  notes         String?\n  active        Boolean   @default(true)\n  createdAt     DateTime  @default(now())\n\n  user  User             @relation(fields: [userId], references: [id], onDelete: Cascade)\n  doses MedicationDose[]\n\n  @@index([userId, active])\n}\n\nmodel MedicationDose {\n  id           String    @id @default(cuid())\n  userId       String\n  medicationId String\n  scheduledAt  DateTime\n  takenAt      DateTime?\n  skipped      Boolean   @default(false)\n  notes        String?\n\n  user       User       @relation(fields: [userId], references: [id], onDelete: Cascade)\n  medication Medication @relation(fields: [medicationId], references: [id], onDelete: Cascade)\n\n  @@index([userId, scheduledAt])\n  @@index([medicationId, scheduledAt])\n}\n\n// ---------- Daily check-in ----------\n\nmodel DailyCheckIn {\n  id             String   @id @default(cuid())\n  userId         String\n  date           DateTime // date only — the day this check-in represents\n  energy         Int? // 1..10\n  painIntensity  String? // 'mild' | 'moderate' | 'severe'\n  painLocations  String? // JSON array\n  painTypes      String? // JSON array\n  flareStatus    String? // 'no' | 'maybe' | 'yes'\n  flareSeverity  String? // 'mild' | 'moderate' | 'severe'\n  sleep          String? // 'poor' | 'okay' | 'good'\n  sleepHours     Float?\n  sleepDisrupted Boolean  @default(false)\n  stress         Int? // 1..10\n  mood           Int? // 1..10\n  medsTaken      String? // 'yes' | 'some' | 'no'\n  sideEffects    String? // JSON array\n  gutIssues      String? // JSON array\n  foodTriggers   String? // JSON array\n  mobility       String? // 'hard' | 'some-difficulty' | 'okay'\n  notes          String?\n  createdAt      DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, date])\n  @@index([userId, date])\n}\n\n// ---------- Diet tracker ----------\n\nmodel DietLog {\n  id       String   @id @default(cuid())\n  userId   String\n  mealType String // 'breakfast' | 'lunch' | 'dinner' | 'snack'\n  foods    String // JSON array of food names\n  triggers String? // JSON array of suspected trigger foods\n  calories Int?\n  notes    String?\n  ateAt    DateTime\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, ateAt])\n}\n\n// ---------- Flare events ----------\n\nmodel FlareEvent {\n  id        String    @id @default(cuid())\n  userId    String\n  startedAt DateTime\n  endedAt   DateTime?\n  severity  Int // 1..10\n  triggers  String? // JSON array\n  locations String? // JSON array of body parts affected\n  notes     String?\n  resolved  Boolean   @default(false)\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, startedAt])\n}\n\n// ---------- Medical records ----------\n\nmodel MedicalRecord {\n  id           String   @id @default(cuid())\n  userId       String\n  title        String\n  type         String // 'lab' | 'imaging' | 'visit' | 'prescription' | 'other'\n  providerName String?\n  date         DateTime\n  fileUrl      String? // stored file (or external link)\n  notes        String?\n  tags         String? // JSON array\n  createdAt    DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, date])\n}\n\n// ---------- Community ----------\n\nmodel CommunityPost {\n  id        String   @id @default(cuid())\n  userId    String\n  content   String\n  tags      String? // JSON array\n  likes     Int      @default(0)\n  createdAt DateTime @default(now())\n\n  user     User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n  comments CommunityComment[]\n\n  @@index([createdAt])\n}\n\nmodel CommunityComment {\n  id        String   @id @default(cuid())\n  postId    String\n  userId    String\n  content   String\n  createdAt DateTime @default(now())\n\n  post CommunityPost @relation(fields: [postId], references: [id], onDelete: Cascade)\n  user User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([postId])\n}\n\n// ---------- Insights (computed patterns) ----------\n\nmodel Insight {\n  id          String   @id @default(cuid())\n  userId      String\n  type        String // 'trigger' | 'pattern' | 'trend' | 'correlation'\n  title       String\n  description String\n  data        String? // JSON payload for chart data\n  severity    String   @default(\"info\") // 'info' | 'warning' | 'positive'\n  createdAt   DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, createdAt])\n}\n\n// ---------- Calendar (aggregated event feed) ----------\n\nmodel CalendarEvent {\n  id              String    @id @default(cuid())\n  userId          String\n  type            String // 'symptom' | 'medication' | 'checkin' | 'flare' | 'appointment'\n  title           String\n  date            DateTime\n  endDate         DateTime?\n  relatedEntityId String?\n  payload         String? // JSON for extra detail\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, date])\n}\n",
